///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getleadcomList
 * @description 대표주관회사(코넥스는 지정자문인) 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getleadcomList = async function(){
    const js_mkrket = $c.session.getUserInfo("market");

    let actionUrl = "/api/listing/common/pop/etc/list-leadcom/select-list";
    if (String(js_mkrket) === "6"){
        actionUrl = "/api/listing/common/pop/etc/select-list-nominated-adviser";
        grd_leadcom.setHeaderValue("h_TEXT", "지정자문인명");
        grd_selectleadcom.setHeaderValue("h_TEXT", "지정자문인명");
    }

    const sbmOptions = {
        id : "sbm_List",
        method: "get",
        action : actionUrl,
        target : "dlt_list=body",
        isProcessMsg : false
    };
    await $c.sbm.executeDynamic(sbmOptions);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록 조회
 * @returns {void}
 * @hidden N
 */
scwin.listSync = async function() {
    await scwin.getleadcomList();
};

/**
 * @method
 * @name add
 * @description 조회 목록의 선택 행을 선택 목록에 추가(중복이면 무시)
 * @returns {void}
 * @hidden N
 */
scwin.add = function() {

    let vValue = dlt_list.getCellData(dlt_list.getRowPosition(), "value");
    let vText = dlt_list.getCellData(dlt_list.getRowPosition(), "text");
    const rowPosition = dlt_selList.getRowCount();
    for (let i = 0; i < dlt_selList.getRowCount(); i++) {
        if (dlt_selList.getCellData(i, "value") === vValue) {
            return;
        }
    }
    dlt_selList.insertRow();

    dlt_selList.setCellData(rowPosition, "value", vValue);
    dlt_selList.setCellData(rowPosition, "text", vText);
};

/**
 * @method
 * @name del
 * @description 선택 목록에서 현재 행 삭제
 * @returns {void}
 * @hidden N
 */
scwin.del = function() {
    // var RowPos = dts_selectleadcom.ValueRow(dts_selectleadcom.RowPosition, MTr_2.ItemText);
    const rowPos = dlt_selList.getRowPosition();
    if (rowPos < 0) {
        return;
    }
    dlt_selList.removeRow(rowPos);
};

/**
 * @method
 * @name confirm
 * @description 선택 목록을 오프너에 전달하고 팝업을 닫는다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function() {
    /*
    var vValue;
    var vText;
    for (i = 0; i <= dlt_selList.getTotalRow(); i++) {
        if (i == 0) {
            vValue = dlt_selList.getCellData(i, "value");
            vText = dlt_selList.getCellData(i, "text");
        } else {
            vValue = vValue + "," + dlt_selList.getCellData(i, "value");
            vText = vText + "," + dlt_selList.getCellData(i, "text");
        }
    }

    //alert("vText :"+vText);
    var fr_setLead = $c.win.getParent().fn_setLeadComNMStr;
    fr_setLead(vValue, vText);

     */

    const resObj = dlt_selList.getInsertedJSON();
    $c.win.closePopup(resObj);
};
